{
  "name": "变温实验控制后端与界面组件",
  "name_en": "Variable-Temperature Experiment Control Backend and GUI Component",
  "manufacturer": "",
  "description": "一个非物理的软件组件，用于协调 Keithley 2400、Keithley 2182 和 Lakeshore 350 的连接、配置、温度斜坡控制、测量采集以及实验界面状态管理，适合变温电学测量流程。",
  "description_en": "A non-physical software component that coordinates connection, configuration, temperature ramp control, measurement acquisition, and GUI state management for a Keithley 2400, Keithley 2182, and Lakeshore 350 in variable-temperature electrical measurement workflows.",
  "actions": [
    {
      "action_name": "auto-configure_instruments",
      "description": "配置 Keithley 2400、Keithley 2182 和 Lakeshore 350 的实验参数。",
      "description_en": "Configure experiment parameters for the Keithley 2400, Keithley 2182, and Lakeshore 350."
    },
    {
      "action_name": "auto-connect",
      "description": "连接到 K2400、K2182 和 Lakeshore 350 的通信地址。",
      "description_en": "Connect to the communication addresses of the K2400, K2182, and Lakeshore 350."
    },
    {
      "action_name": "auto-set_heater_range",
      "description": "设置 Lakeshore 温控输出的加热量程。",
      "description_en": "Set the heater range for a Lakeshore temperature-control output."
    },
    {
      "action_name": "auto-set_setpoint",
      "description": "设置 Lakeshore 温控输出的目标温度。",
      "description_en": "Set the target temperature for a Lakeshore temperature-control output."
    },
    {
      "action_name": "auto-shutdown",
      "description": "停止实验并关闭相关仪器连接与输出。",
      "description_en": "Stop the experiment and shut down related instrument connections and outputs."
    },
    {
      "action_name": "auto-start_ramp",
      "description": "启动到目标温度的升降温斜坡控制。",
      "description_en": "Start a temperature ramp to the target temperature."
    },
    {
      "action_name": "auto-get_measurement",
      "description": "获取测量读数。",
      "description_en": "get measurement reading"
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取温度读数。",
      "description_en": "get temperature reading"
    },
    {
      "action_name": "auto-setup_styles",
      "description": "设置图形界面的显示样式。",
      "description_en": "Set up the visual styles of the graphical user interface."
    },
    {
      "action_name": "auto-create_widgets",
      "description": "创建实验控制界面的控件。",
      "description_en": "Create widgets for the experiment control interface."
    },
    {
      "action_name": "auto-log",
      "description": "记录实验运行过程中的日志信息。",
      "description_en": "Log messages during experiment operation."
    },
    {
      "action_name": "auto-start_experiment",
      "description": "启动变温测量实验流程。",
      "description_en": "Start the variable-temperature measurement workflow."
    },
    {
      "action_name": "auto-stop_experiment",
      "description": "停止变温测量实验流程。",
      "description_en": "Stop the variable-temperature measurement workflow."
    },
    {
      "action_name": "auto-set_ui_state",
      "description": "设置界面控件的启用状态与交互状态。",
      "description_en": "Set the enabled and interaction state of the user interface."
    }
  ],
  "tag_hints": [
    "variable-temperature measurement",
    "Keithley 2400",
    "Keithley 2182",
    "Lakeshore 350",
    "temperature ramp control",
    "GUI experiment control",
    "VISA instrument coordination"
  ]
}

